import data from '@/data/players.json'; import type { Player } from '@/types/player';
const players=data as Player[]; const order={GK:0,DF:1,MF:2,FW:3};
export const getPlayers=()=>[...players];
export const getActivePlayers=()=>players.filter(p=>p.active).sort((a,b)=>order[a.position]-order[b.position]||a.number-b.number);
export const getPlayerById=(id:string)=>players.find(p=>p.playerId===id);
export const getPlayerName=(id:string|null)=>id ? getPlayerById(id)?.name ?? '不明な選手' : '対戦相手';
